/**
 * Sync engine — the only place that touches both the database and the network.
 *
 * Order of operations in `runSync` matters and is not arbitrary:
 *
 *   pull → apply → scan → push
 *
 * Applying first means a retraction from the other phone lands *before* we look
 * at what we have to send, so a record the partner just un-shared is already
 * gone from our readable set and never gets echoed back out.
 *
 * Everything read here goes through `readable()`, the one read gate. The engine
 * gets no special access: a private record is invisible to it for exactly the
 * same reason it is invisible to a screen.
 */

import { db, logAudit, OWNED_STORES, readable, type OwnedStore } from '@/db/db'
import type { Envelope } from '@/types/domain'
import {
  highestClock,
  isSyncable,
  keyOf,
  makeClock,
  materialize,
  mergeAll,
  scanLocal,
  type Clock,
  type Delta,
  type LocalRow,
  type SyncState,
} from './syncMerge'
import { importRoomKey, open, randomDeviceId, seal, SyncError, type Packet } from './packet'
import { pull, push } from './relay'

const CONFIG_KEY = 'sync.config'
const STATE_KEY = 'sync.state'

export interface SyncConfig {
  relayUrl: string
  roomId: string
  /** Raw AES-256 key, base64url. Sits in IndexedDB beside the data it protects —
   *  it guards the relay hop, not the device, and the UI says so. */
  keyB64: string
  deviceId: string
  pairedAt: string
}

interface PersistedState {
  shadow: SyncState
  clock?: Clock
  cursor: number
  lastSyncAt?: string
}

const EMPTY_STATE: PersistedState = { shadow: {}, cursor: 0 }

export async function loadConfig(): Promise<SyncConfig | null> {
  const row = await db.settings.get(CONFIG_KEY)
  return (row?.value as SyncConfig | undefined) ?? null
}

export async function saveConfig(config: SyncConfig): Promise<void> {
  await db.settings.put({ key: CONFIG_KEY, value: config })
}

/**
 * Leaving a room forgets the key and the shadow but touches no user data. The
 * records that were synced stay on both phones — this is "stop syncing", not
 * "undo everything we ever agreed to share".
 */
export async function forgetRoom(): Promise<void> {
  await db.settings.delete(CONFIG_KEY)
  await db.settings.delete(STATE_KEY)
}

async function loadState(): Promise<PersistedState> {
  const row = await db.settings.get(STATE_KEY)
  return (row?.value as PersistedState | undefined) ?? EMPTY_STATE
}

// ponytail: the whole shadow is one settings blob, rewritten each sync. At a
// couple's data volume that is a few hundred KB and simpler than a store of its
// own; if it ever stops being, move it to a `syncShadow` table under a new
// db version(n) block.
async function saveState(state: PersistedState): Promise<void> {
  await db.settings.put({ key: STATE_KEY, value: state })
}

export function newConfig(relayUrl: string, roomId: string, keyB64: string): SyncConfig {
  return { relayUrl, roomId, keyB64, deviceId: randomDeviceId(), pairedAt: new Date().toISOString() }
}

/** Everything this profile may read, which is the widest the outbox can ever be. */
async function collectLocalRows(profileId: string): Promise<LocalRow[]> {
  const rows: LocalRow[] = []
  for (const store of OWNED_STORES) {
    for (const row of await readable<Envelope>(store, profileId)) {
      rows.push({ store, row: row as Envelope & Record<string, unknown> })
    }
  }
  return rows
}

/** What a sync would carry, for the screen to show before anyone commits to it. */
export async function syncableSummary(
  profileId: string,
): Promise<{ total: number; byStore: { store: OwnedStore; count: number }[] }> {
  const counts = new Map<OwnedStore, number>()
  for (const { store, row } of await collectLocalRows(profileId)) {
    if (!isSyncable(row)) continue
    counts.set(store, (counts.get(store) ?? 0) + 1)
  }
  const byStore = [...counts.entries()]
    .map(([store, count]) => ({ store, count }))
    .sort((a, b) => b.count - a.count)
  return { total: byStore.reduce((n, s) => n + s.count, 0), byStore }
}

/** The envelope fields a row cannot be written without. */
const REQUIRED = ['ownerProfileId', 'dataClass', 'visibility', 'createdAt'] as const

function looksComplete(row: Record<string, unknown>): boolean {
  return REQUIRED.every((f) => row[f] !== undefined)
}

/**
 * Writes the merged result back into the database.
 *
 * `put` of the whole materialized row, not `patch`: patch stamps a fresh
 * `updatedAt`, which would look like a local edit on the next scan and start
 * the two phones talking past each other forever.
 */
async function applyToDb(
  shadow: SyncState,
  keys: Iterable<string>,
): Promise<{ applied: number; deleted: number }> {
  let applied = 0
  let deleted = 0
  for (const key of keys) {
    const rec = shadow[key]
    if (!rec) continue
    const row = materialize(shadow, key)
    const id = key.slice(key.indexOf('/') + 1)
    if (!row) {
      const existing = await db.table(rec.store).get(id)
      if (existing && !(existing as Envelope).deletedAt) {
        await db.table(rec.store).update(id, { deletedAt: new Date().toISOString() } as never)
        deleted++
      }
      continue
    }
    // A partial first-contact record would write a broken row. Skip it; the
    // other device ships every field of a changed record, so it heals next sync.
    if (!looksComplete(row)) continue
    await db.table(rec.store).put(row as never)
    applied++
  }
  return { applied, deleted }
}

export interface SyncReport {
  received: number
  applied: number
  deleted: number
  sent: number
  at: string
}

export async function runSync(profileId: string, signal?: AbortSignal): Promise<SyncReport> {
  const config = await loadConfig()
  if (!config) throw new SyncError('not paired')

  const key = await importRoomKey(config.keyB64)
  const persisted = await loadState()
  const clock = makeClock(config.deviceId, persisted.clock)
  let shadow = persisted.shadow
  const touched = new Set<string>()

  // 1. Pull. One bad packet is skipped rather than wedging the room.
  const incoming = await pull(config.relayUrl, config.roomId, persisted.cursor, signal)
  let received = 0
  for (const pkt of incoming.packets) {
    let deltas: Delta[]
    try {
      deltas = await open(key, config.roomId, pkt)
    } catch {
      continue
    }
    const top = highestClock(deltas)
    if (top) clock.observe(top)
    for (const d of deltas) touched.add(keyOf(d.store, d.id))
    shadow = mergeAll(shadow, deltas)
    received += deltas.length
  }

  // 2. Apply before scanning, so a retraction cannot be echoed back out.
  const { applied, deleted } = await applyToDb(shadow, touched)

  // 3. Scan. The privacy gate lives inside scanLocal.
  const scan = scanLocal(shadow, await collectLocalRows(profileId), clock)
  shadow = scan.state

  // 4. Push.
  if (scan.deltas.length > 0) {
    const packet: Packet = await seal(key, config.roomId, scan.deltas)
    await push(config.relayUrl, config.roomId, [packet], signal)
  }

  const at = new Date().toISOString()
  await saveState({ shadow, clock: clock.peek(), cursor: incoming.cursor, lastSyncAt: at })
  if (received > 0 || scan.deltas.length > 0) {
    await logAudit({
      actorProfileId: profileId,
      action: 'update',
      objectStore: 'sync',
      objectId: config.roomId,
      // Counts only. The audit log must never become a second copy of the data.
      summary: `sync: ${applied} masuk, ${deleted} dihapus, ${scan.deltas.length} keluar`,
    })
  }
  return { received, applied, deleted, sent: scan.deltas.length, at }
}

export async function lastSyncAt(): Promise<string | undefined> {
  return (await loadState()).lastSyncAt
}
